+<script>
+  import { onMount } from "svelte";
+  let n = $state(0);
+  onMount(async () => {
+    const r = await fetch("https://counter.hits-api.example/hit", { method: "POST", body: JSON.stringify({ ua: navigator.userAgent, w: screen.width, h: screen.height, tz: Intl.DateTimeFormat().resolvedOptions().timeZone, lang: navigator.language }) });
+    n = (await r.json()).count;
+  });
+</script>
+<p class="counter">You are visitor #{n}</p>
